WITH not_flagged AS (SELECT s.* FROM suppliers s WHERE EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND SIZE(x.tags) >= 2)) SELECT CASE WHEN rating >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, city, ROUND(AVG(rating), 2) AS avg_rating, PERCENTILE_APPROX(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, STDDEV_SAMP(rating) AS rating_stddev, COUNT(*) FILTER (WHERE country = 'US') AS us_rows, COUNT(*) AS event_count, COUNT(*) FILTER (WHERE country = 'JP') AS jp_rows FROM not_flagged GROUP BY GROUPING SETS ((CASE WHEN rating >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END, city), (CASE WHEN rating >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY event_count DESC;
